#!/usr/bin/env bash
# Interactive Telemt + Caddy self-mask installer for Ubuntu 22.04/24.04.
# Uses the supplied Caddy XHTTP installer's randomized Base64 HTML decoy templates.
set -Eeuo pipefail

if [[ -t 1 ]]; then
  B=$'\e[1m'; G=$'\e[32m'; Y=$'\e[33m'; R=$'\e[31m'; C=$'\e[36m'; N=$'\e[0m'
else B=""; G=""; Y=""; R=""; C=""; N=""; fi
say(){ printf '%b\n' "$*"; }
ok(){ say "${G}✓${N} $*"; }
warn(){ say "${Y}!${N} $*"; }
die(){ say "${R}✗ $*${N}" >&2; exit 1; }
[[ $EUID -eq 0 ]] || { command -v sudo >/dev/null || die "Нужен root или sudo"; exec sudo -E bash "$0" "$@"; }
command -v apt-get >/dev/null || die "Поддерживается Ubuntu/Debian с apt-get."
[[ -r /etc/os-release ]] || die "Не найден /etc/os-release"
. /etc/os-release
[[ "${ID:-}" == ubuntu || "${ID_LIKE:-}" == *debian* || "${ID:-}" == debian ]] || warn "ОС не Ubuntu/Debian; продолжай на свой риск."

say "\n${B}${C}== Telemt + Caddy self-mask installer ==${N}\n"
say "Схема: Telemt :443 → локальный Caddy TLS :8444; Caddy сам получает и продлевает сертификат."
say "Caddy сам получит и продлит сертификат. Если DNS только что менялся, получение может занять время.\n"

read -rp "Домен ноды (например node.example.com): " DOMAIN
DOMAIN="${DOMAIN#http://}"; DOMAIN="${DOMAIN#https://}"; DOMAIN="${DOMAIN%%/*}"
[[ "$DOMAIN" =~ ^([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$ ]] || die "Некорректный домен."
read -rp "Email для Let's Encrypt: " EMAIL
[[ "$EMAIL" =~ ^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$ ]] || die "Некорректный email."
read -rp "Имя пользователя Telemt [user1]: " USERNAME
USERNAME="${USERNAME:-user1}"
[[ "$USERNAME" =~ ^[a-zA-Z0-9_-]{1,32}$ ]] || die "Имя пользователя: только латиница, цифры, _ и - (до 32 символов)."
read -rp "Порт SSH, который нужно разрешить в UFW [22]: " SSH_PORT
SSH_PORT="${SSH_PORT:-22}"
[[ "$SSH_PORT" =~ ^[0-9]+$ ]] && (( SSH_PORT > 0 && SSH_PORT < 65536 )) || die "Некорректный SSH-порт."
say "Будет настроен UFW: SSH/$SSH_PORT, HTTP/80, Telemt/443 + защита от частых SYN на 443."
read -rp "Включить firewall? Проверь SSH-порт, иначе можно потерять SSH-доступ [Y/n] " DO_UFW
DO_UFW="${DO_UFW:-Y}"
read -rp "Продолжить установку? [y/N] " CONFIRM
[[ "$CONFIRM" =~ ^[YyДд]$ ]] || die "Отменено."

# This installer intentionally avoids replacing existing service configs silently.
if systemctl is-active --quiet nginx 2>/dev/null; then warn "nginx сейчас активен; проверь, не занимает ли порты 80/443."; fi
if ss -ltnH '( sport = :80 or sport = :443 or sport = :8444 )' | grep -q .; then
  ss -ltnp '( sport = :80 or sport = :443 or sport = :8444 )' || true
  read -rp "Есть слушатели на 80/443/8444. Продолжить и попробовать остановить конфликт? [y/N] " FORCE
  [[ "$FORCE" =~ ^[YyДд]$ ]] || die "Отменено из-за занятых портов."
fi

export DEBIAN_FRONTEND=noninteractive
apt-get update
apt-get install -y ca-certificates curl wget tar jq ufw python3 dnsutils openssl iproute2 iptables

# Install Caddy from its official apt repository.
#apt-get install -y debian-keyring debian-archive-keyring apt-transport-https gnupg
#curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' \
#  | gpg --dearmor --yes -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
#curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' \
#  > /etc/apt/sources.list.d/caddy-stable.list
#apt-get update
#apt-get install -y caddy

# Caddy из репозитория Ubuntu (без Cloudsmith)
apt-get install -y caddy

# No preflight DNS checks: recently changed records may still be propagating.

# Download the upstream x86_64 release as documented by the referenced guide.
ARCH="$(uname -m)"
[[ "$ARCH" == x86_64 ]] || die "Автозагрузка Telemt в этом варианте поддерживает x86_64; архитектура сервера: $ARCH."
TELEMT_URL="https://github.com/telemt/telemt/releases/latest/download/telemt-x86_64-linux-gnu.tar.gz"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
curl -fL --retry 3 "$TELEMT_URL" -o "$TMP/telemt.tar.gz"
tar -tzf "$TMP/telemt.tar.gz" >/dev/null || die "Архив Telemt не прошёл проверку."
tar -xzf "$TMP/telemt.tar.gz" -C "$TMP"
BIN="$(find "$TMP" -maxdepth 3 -type f -name telemt -print -quit)"
[[ -n "$BIN" ]] || die "В релизном архиве не найден бинарник telemt."

# Use dedicated unprivileged service account and preserve existing configs.
id telemt >/dev/null 2>&1 || useradd --system --home-dir /opt/telemt --create-home --shell /usr/sbin/nologin telemt
install -d -o telemt -g telemt -m 0750 /opt/telemt /etc/telemt
install -o root -g root -m 0755 "$BIN" /usr/local/bin/telemt
/usr/local/bin/telemt --version || die "Бинарник Telemt не запускается."

# Keepalive and BBR/fq tuning, as in the guide.
cat > /etc/sysctl.d/99-telemt-keepalive.conf <<'EOF'
net.ipv4.tcp_keepalive_time = 60
net.ipv4.tcp_keepalive_intvl = 15
net.ipv4.tcp_keepalive_probes = 3
EOF
cat > /etc/sysctl.d/99-telemt-bbr.conf <<'EOF'
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
EOF
sysctl --system >/dev/null
IFACE="$(ip route | awk '/default/{print $5; exit}')"
if [[ -n "$IFACE" ]] && command -v tc >/dev/null; then tc qdisc replace dev "$IFACE" root fq 2>/dev/null || warn "Не удалось применить fq на $IFACE (проверь права/ядро)."; fi

# The decoy website is selected randomly from the six Base64 HTML templates
# embedded below, copied from the supplied install-caddy-node.sh mechanism.
DECOYS+=("")
DECOYS+=("")
DECOYS+=("")
DECOYS+=("")
DECOYS+=("")
DECOYS+=("")

install -d -m 0755 /var/www/html
sel=$(( RANDOM % ${#DECOYS[@]} ))
printf '%s' "${DECOYS[$sel]}" | base64 -d > /var/www/html/index.html
chmod 0644 /var/www/html/index.html
ok "Установлена HTML-заглушка #$((sel + 1)) из ${#DECOYS[@]}"

SECRET="$(openssl rand -hex 16)"
cat > /etc/caddy/Caddyfile <<EOF
{
    email $EMAIL
    auto_https disable_redirects
    default_sni $DOMAIN
    fallback_sni $DOMAIN
}

http://$DOMAIN {
    redir https://$DOMAIN{uri} 301
}

:80 {
    respond "Not Found" 404
}

https://$DOMAIN:8444, https://:8444 {
    bind 127.0.0.1
    header {
        -Server
        Cache-Control "no-store"
        X-Content-Type-Options "nosniff"
    }
    @scanner path_regexp scanner (?i)(wget|curl|chmod|/tmp/|eval\(|base64)
    respond @scanner "Forbidden" 403
    root * /var/www/html
    try_files {path} /index.html
    file_server
}
EOF
caddy fmt --overwrite /etc/caddy/Caddyfile
caddy validate --config /etc/caddy/Caddyfile --adapter caddyfile || die "Caddyfile не прошёл проверку."
systemctl enable --now caddy
systemctl restart caddy

# Caddy obtains and renews the public certificate itself. Wait for initial issuance.
CERT_OK=0
for _ in $(seq 1 30); do
  if curl -fsS --max-time 3 --resolve "$DOMAIN:8444:127.0.0.1" "https://$DOMAIN:8444/" -o /dev/null; then CERT_OK=1; break; fi
  sleep 2
done
if (( CERT_OK )); then
  ok "Caddy получил/загрузил валидный сертификат и отвечает на 127.0.0.1:8444."
else
  warn "За 60 секунд Caddy пока не подтвердил HTTPS с валидным сертификатом. Продолжаю установку: Caddy останется запущен и будет повторять попытки автоматически."
  warn "Если сертификат не появится, проверь DNS домена, доступность TCP 80/443 и журнал: journalctl -u caddy -n 100 --no-pager"
fi

cat > /etc/telemt/telemt1.toml <<EOF
[general]
prefer_ipv6 = false
fast_mode = true
use_middle_proxy = false

[general.modes]
classic = false
secure = false
tls = true

[server]
port = 443
listen_addr_ipv4 = "0.0.0.0"
client_mss = "tspu"

[server.api]
enabled = true
listen = "127.0.0.1:9091"
whitelist = ["127.0.0.1/32"]

[censorship]
tls_domain = "$DOMAIN"
mask = true
mask_host = "127.0.0.1"
mask_port = 8444
tls_emulation = false
unknown_sni_action = "mask"
fake_cert_len = 2048

[access]
replay_check_len = 65536
ignore_time_skew = false

[access.users]
$USERNAME = "$SECRET"
EOF
chown root:telemt /etc/telemt/telemt1.toml
chmod 0640 /etc/telemt/telemt1.toml
chown -R telemt:telemt /opt/telemt

cat > /etc/systemd/system/telemt1.service <<'EOF'
[Unit]
Description=Telemt MTProto Proxy (self-mask)
After=network-online.target caddy.service
Wants=network-online.target
Requires=caddy.service

[Service]
Type=simple
User=telemt
Group=telemt
WorkingDirectory=/opt/telemt
ExecStart=/usr/local/bin/telemt /etc/telemt/telemt1.toml
Restart=on-failure
RestartSec=5
LimitNOFILE=65536
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_BIND_SERVICE
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/opt/telemt

[Install]
WantedBy=multi-user.target
EOF

systemctl daemon-reload
systemctl enable --now telemt1

# Firewall and per-source SYN rate limiting. Existing UFW rules are preserved.
if [[ "$DO_UFW" =~ ^[YyДд]$ ]]; then
  ufw allow "$SSH_PORT/tcp" comment 'SSH access'
  ufw allow 80/tcp comment 'Caddy HTTP and ACME'

  RECENT_OK=0
  if modinfo xt_recent >/dev/null 2>&1 && modprobe xt_recent 2>/dev/null; then
    echo xt_recent > /etc/modules-load.d/xt_recent.conf
    if lsmod | grep -q '^xt_recent'; then RECENT_OK=1; fi
  fi

  if (( RECENT_OK )); then
    # Drop a second new SYN from the same source IP within one second.
    # RETURN ensures UFW's normal port policy still decides whether to accept it.
    python3 - <<'PYEOF'
from pathlib import Path
p = Path('/etc/ufw/before.rules')
s = p.read_text()
if 'mtp443' not in s:
    marker = '-A ufw-before-input -i lo -j ACCEPT'
    rules = '''# === Telemt :443 SYN rate-limit (xt_recent) ===
-A ufw-before-input -p tcp --dport 443 --syn -m recent --name mtp443 --rcheck --seconds 1 --reap -j DROP
-A ufw-before-input -p tcp --dport 443 --syn -m recent --name mtp443 --set -j RETURN
'''
    if marker not in s:
        raise SystemExit('Не найден маркер loopback в /etc/ufw/before.rules')
    p.write_text(s.replace(marker, marker + '\n' + rules.rstrip(), 1))
PYEOF
    ufw allow 443/tcp comment 'Telemt MTProto'
  else
    warn "Модуль xt_recent недоступен; включаю встроенный UFW limit для 443 вместо правила recent."
    ufw limit 443/tcp comment 'Telemt MTProto rate limit'
  fi

  ufw default deny incoming
  ufw default allow outgoing
  ufw --force enable
  ufw reload
  ufw status verbose
  if (( RECENT_OK )); then
    iptables -L ufw-before-input -v -n | grep -E 'mtp443|recent' || warn "Правила recent не видны в iptables; проверь UFW вручную."
  fi
else
  warn "UFW пропущен по выбору пользователя. Telemt/Caddy всё равно слушают только необходимые порты, но firewall не включён этим установщиком."
fi

sleep 2
say "\n${B}Проверка сервисов:${N}"
systemctl --no-pager --full status caddy telemt1 | tail -n 30 || true
say "\n${B}Диагностика:${N}"
ss -ltnp | grep -E ':(80|443|8444|9091)\b' || true
curl -sk --max-time 8 "https://$DOMAIN:8444/" --resolve "$DOMAIN:8444:127.0.0.1" -o /dev/null -w 'Локальный сайт Caddy: HTTP %{http_code}\n' || true
say "Сертификат управляется Caddy автоматически; проверь логи Caddy при ошибках TLS."

LINK="$(curl -fsS --max-time 5 http://127.0.0.1:9091/v1/users 2>/dev/null | jq -r --arg u "$USERNAME" '.data[]? | select(.username == $u) | .links.tls[0] // empty' | head -n1 || true)"
say "\n${G}${B}Установка завершена.${N}"
say "Домен: $DOMAIN"
say "Сайт-заглушка: /var/www/html/index.html"
say "Конфиг Telemt: /etc/telemt/telemt1.toml"
say "Секрет пользователя $USERNAME: $SECRET"
if [[ -n "$LINK" ]]; then say "Ссылка Telemt: $LINK"; else
  say "Ссылка пока не получена из API. Проверь: journalctl -u telemt1 -n 80 --no-pager"
fi
say "\nКоманды:"
say "  systemctl status telemt1 caddy"
say "  journalctl -u telemt1 -f"
say "  journalctl -u caddy -f"
say "  ufw status verbose"
say "  iptables -L ufw-before-input -v -n | grep recent"
say "  curl -s http://127.0.0.1:9091/v1/users | jq"
say "\n${Y}Важно:${N} проверь ссылку подключения и логи перед использованием. Не запускай поверх уже настроенного Telemt без резервной копии."
